import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { projects } from '../constants/projects';
import { useNavigate } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';

const WorksDetail = () => {
    const { slug } = useParams();
    const project = projects.find((p) => p.slug === slug);
    const navigate = useNavigate();
    const [fadeIn, setFadeIn] = useState(false);

    useEffect(() => {
        // ページマウント時にフェードイン開始
        setFadeIn(true);
    }, []);

    if (!project) return <div>Project not found</div>;

    return (
        <div className='works'>
            <div className='header'>
                <a href={'/'}>
                    <img src='/assets/Logo.svg' alt='Logo' className='logo' />
                </a>
            </div>

            <div
                className='image-header'
                style={{
                    opacity: fadeIn ? 1 : 0,
                    transform: fadeIn ? 'translateY(0px)' : 'translateY(10px)',
                    transition: 'opacity 0.6s ease-in-out, transform 0.6s ease-in-out',
                }}
            >
                <img className='img-header' src={project.imageHeader} />
            </div>

            <div
                className='body-works'
                style={{
                    opacity: fadeIn ? 1 : 0,
                    transform: fadeIn ? 'translateY(0px)' : 'translateY(10px)',
                    transition: 'opacity 0.6s ease-in-out, transform 0.6s ease-in-out',
                }}
            >
                <h1 className='heading'>
                    {project.title.split('\n').map((line, index) => (
                        <React.Fragment key={index}>
                            {line}
                            <br />
                        </React.Fragment>
                    ))}
                </h1>
                <div className='container-info'>
                    <div className='container-info-2'>
                        <span className='text-wrapper'>制作期間</span>
                        <p className='body-2'>{project.timeline}</p>
                    </div>
                    <div className='container-info-2'>
                        <span className='text-wrapper'>チーム</span>
                        <p className='body-2'>
                            {project.team.split('\n').map((line, index) => (
                                <React.Fragment key={index}>
                                    {line}
                                    <br />
                                </React.Fragment>
                            ))}
                        </p>
                    </div>
                    <div className='container-info-2'>
                        <span className='text-wrapper'>使用ツール</span>
                        <p className='body-2'>{project.tools}</p>
                    </div>
                    <div className='container-info-2'>
                        <span className='text-wrapper'>カテゴリー</span>
                        <p className='body-2'>{project.discipline}</p>
                    </div>
                </div>

                <div className='div-2'>
                    {project.sections.map((section, index) => (
                        <div key={index} className='container-info-sub'>
                            <h2 className='heading-2'>{section.heading}</h2>
                            {section.heading2 && <h3 className='heading-3'>{section.heading2}</h3>}
                            <div className='body-2'>
                                <ReactMarkdown
                                    breaks={true}
                                    components={{
                                        // マークダウンの見出しに既存のクラスを適用
                                        h1: ({ node, ...props }) => <h1 className='heading' {...props} />,
                                        h2: ({ node, ...props }) => <h2 className='heading-2' {...props} />,
                                        h3: ({ node, ...props }) => <h3 className='heading-3' {...props} />,
                                        ol: ({ node, ...props }) => (
                                            <ol className='numbered-list' style={{ margin: 0 }} {...props} />
                                        ),
                                        ul: ({ node, ...props }) => (
                                            <ul className='body-list' style={{ margin: 0 }} {...props} />
                                        ),

                                        li: ({ node, ...props }) => <li {...props} />,
                                    }}
                                >
                                    {section.body}
                                </ReactMarkdown>
                            </div>

                            {/* Render lists if they exist */}
                            {section.lists &&
                                section.lists.map((list, listIndex) => (
                                    <div key={listIndex} className='list-container'>
                                        {list.title && <div className='list-title'>{list.title}</div>}
                                        <ul className='body-list'>
                                            {list.items.map((item, itemIndex) => (
                                                <li key={itemIndex}>{item}</li>
                                            ))}
                                        </ul>
                                    </div>
                                ))}

                            {section.images && (
                                <div className='image-grid'>
                                    {section.images.map((image, idx) => (
                                        <img
                                            key={idx}
                                            className='img'
                                            src={image}
                                            alt={`${project.title} ${index + 1}`}
                                        />
                                    ))}
                                </div>
                            )}
                        </div>
                    ))}
                </div>

                {project.externalUrls && project.externalUrls.length > 0 && (
                    <div className='external-url-section'>
                        {project.externalUrls.map((url, index) => (
                            <a
                                key={index}
                                className='external-url'
                                href={url.href}
                                target='_blank'
                                rel='noopener noreferrer'
                            >
                                {url.text}
                            </a>
                        ))}
                    </div>
                )}

                <div className='container-link'>
                    {project.links.map((link, index) => (
                        <a key={index} href={link.href} className='link' target='_blank'>
                            <span className='body-3'>{link.text}</span>
                        </a>
                    ))}
                </div>
                <button className='back-button' onClick={() => navigate('/works')}>
                    <img src='/assets/Arrow.svg' alt='Back' />
                </button>
            </div>

            <div className='footer'></div>
        </div>
    );
};

export default WorksDetail;
